// main.c — C code calling assembly functions
#include <stdio.h>

// Declare assembly functions
extern long asm_add(long a, long b);
extern long asm_array_sum(const long *arr, long count);
extern void asm_reverse_array(long *arr, long count);

int main() {
    // Test asm_add
    long sum = asm_add(100, 200);
    printf("asm_add(100, 200) = %ld\n", sum);

    // Test asm_array_sum
    long arr[] = {10, 20, 30, 40, 50};
    long total = asm_array_sum(arr, 5);
    printf("asm_array_sum = %ld\n", total);

    // Test asm_reverse_array
    printf("Before reverse: ");
    for (int i = 0; i < 5; i++) printf("%ld ", arr[i]);
    printf("\n");

    asm_reverse_array(arr, 5);

    printf("After reverse:  ");
    for (int i = 0; i < 5; i++) printf("%ld ", arr[i]);
    printf("\n");

    return 0;
}

// inline_asm.c — Inline assembly in GCC/Clang
#include <stdio.h>

int main() {
    long a = 10, b = 20, result;

    // Simple inline assembly: result = a + b
    asm volatile (
        "add %[b], %[a]"          // Instruction
        : "=r" (result)           // Output: result in a register
        : "r" (a), [b] "r" (b)    // Inputs: a and b in registers
        :                         // No clobbers
    );
    // Note: This example is conceptual; real add modifies first operand

    // Better example: multiply with result in RDX:RAX
    unsigned long long x = 0xFFFFFFFF;
    unsigned long long y = 0xFFFFFFFF;
    unsigned long long hi, lo;

    asm volatile (
        "mulq %[y]"               // RDX:RAX = RAX * y
        : "=a" (lo), "=d" (hi)   // Outputs: lo=RAX, hi=RDX
        : "a" (x), [y] "r" (y)    // Input: x in RAX, y in any register
        :                         // No additional clobbers
    );

    printf("0x%llx * 0x%llx = 0x%llx%016llx\n", x, y, hi, lo);

    // CPUID example: get processor info
    unsigned int eax, ebx, ecx, edx;
    asm volatile (
        "cpuid"
        : "=a" (eax), "=b" (ebx), "=c" (ecx), "=d" (edx)
        : "a" (0)                 // Input: EAX = 0 (get vendor string)
    );

    char vendor[13] = {0};
    *(unsigned int*)&vendor[0] = ebx;
    *(unsigned int*)&vendor[4] = edx;
    *(unsigned int*)&vendor[8] = ecx;
    printf("CPU Vendor: %s\n", vendor);

    return 0;
}

// test_string_lib.c — Test harness for assembly string library
#include <stdio.h>
#include <string.h>

// Declare assembly functions
extern size_t asm_strlen(const char *s);
extern char *asm_strcpy(char *dest, const char *src);
extern int asm_strcmp(const char *s1, const char *s2);
extern char *asm_strchr(const char *s, int c);
extern void *asm_memset(void *s, int c, size_t n);

int main() {
    // Test strlen
    const char *test = "Hello, Assembly!";
    size_t len1 = strlen(test);
    size_t len2 = asm_strlen(test);
    printf("strlen: %zu, asm_strlen: %zu -> %s\n",
           len1, len2, len1 == len2 ? "PASS" : "FAIL");

    // Test strcpy
    char buf1[32], buf2[32];
    strcpy(buf1, test);
    asm_strcpy(buf2, test);
    printf("strcpy: '%s', asm_strcpy: '%s' -> %s\n",
           buf1, buf2, strcmp(buf1, buf2) == 0 ? "PASS" : "FAIL");

    // Test strcmp
    int r1 = strcmp("abc", "abd");
    int r2 = asm_strcmp("abc", "abd");
    printf("strcmp: %d, asm_strcmp: %d -> %s\n",
           r1, r2, (r1 < 0 && r2 < 0) || (r1 == r2) || (r1 > 0 && r2 > 0) ? "PASS" : "FAIL");

    // Test strchr
    char *p1 = strchr(test, 'A');
    char *p2 = asm_strchr(test, 'A');
    printf("strchr: %p, asm_strchr: %p -> %s\n",
           (void*)p1, (void*)p2, p1 == p2 ? "PASS" : "FAIL");

    // Test memset
    char m1[10] = {0}, m2[10] = {0};
    memset(m1, 'X', 9);
    asm_memset(m2, 'X', 9);
    printf("memset: '%s', asm_memset: '%s' -> %s\n",
           m1, m2, memcmp(m1, m2, 10) == 0 ? "PASS" : "FAIL");

    return 0;
}
